A search box uses this hook with a 300 ms delay. The user types "r", "e", "a" within 300 ms. What does the debounced value do?

```jsx
function useDebounce(value, delay) {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    setTimeout(() => setDebounced(value), delay);
  }, [value, delay]);
  return debounced;
}
```

The save resolves with `{ ok: false }`, and the parent's `todos` prop never changes. What does the list show once the action has finished?

```jsx
function Todos({ todos, saveTodo }) {
  const [optimistic, addOptimistic] = useOptimistic(
    todos,
    (current, title) => [...current, title]
  );
  async function add(formData) {
    const title = formData.get('title');
    addOptimistic(title);
    await saveTodo(title);
  }
  return <form action={add}>{/* renders optimistic */}</form>;
}
```

