A caller uses this hook as `useFetch('/api/items', { headers: { Accept: 'application/json' } })`. Which three are real problems? (Choose three.)

```jsx
function useFetch(url, options) {
  const [data, setData] = useState(null);
  const refetch = () =>
    fetch(url, options).then(r => r.json()).then(setData);
  useEffect(() => {
    refetch();
  }, [url, options]);
  return { data, refetch };
}
```

